        SwarmWitnessResult::Indeterminate(SwarmWitnessIndeterminate::DeclarationCap),
    );
    assert_eq!(
        counters,
        SwarmWitnessCounters {
            root_clone_applies: 1,
            ..Default::default()
        }
    );
}

